                 \draw[thick] (A) -- (H);
                  \draw[thick] (B) -- (K);

    % Gán nhãn cho các điểm
    \node[above left] at (0,3) {$A $};
            \node[above right] at (4,3) {$B $};
            \node[below right] at (6,0) {$C $};
            \node[below left] at (-2,0) {$D $};
                \node[below] at (H) {$H $};
                  \node[below] at (K) {$K $};
